}

.mes .mes_reasoning_details[open] {
    margin-top: 1.7em !important;
}

/* 反馈 2：世界书 select2 多选框占位文字被裁切 */
.select2-container--default .select2-selection--multiple {
    min-height: 2.2em !important;
    height: auto !important;
    padding: 2px 6px !important;
    line-height: 1.6 !important;
    overflow: visible !important;
}

.select2-container--default .select2-selection--multiple .select2-selection__rendered {
    display: block !important;
    padding: 0 !important;
    line-height: 1.6 !important;
    white-space: normal !important;
}

.select2-container--default .select2-search--inline {
    display: block !important;
    width: 100% !important;
}

.select2-container--default .select2-search--inline .select2-search__field {
    width: 100% !important;
    min-width: 0 !important;
    height: auto !important;
    margin: 0 !important;
    padding: 2px 0 !important;
    font-family: var(--song) !important;
    font-size: 0.95em !important;
    color: var(--ink) !important;
    background: transparent !important;
    border: 0 !important;
}

.select2-container--default .select2-search--inline .select2-search__field::placeholder {
    color: var(--g2) !important;
    opacity: 1;
}

.select2-container .select2-selection--multiple .select2-selection__choice {
    margin: 2px 4px 2px 0 !important;
    padding: 0 6px !important;
    line-height: 1.5 !important;
}

/* 代码高亮：白纸上的 highlight.js 配色（墨黑 / 三联红 / 灰） */
.mes_text > pre code.hljs,
.mes_text > pre code {
    color: var(--ink) !important;
    background: transparent !important;
}

.hljs-keyword, .hljs-selector-tag, .hljs-built_in, .hljs-name, .hljs-tag { color: var(--red) !important; font-weight: 700; }
.hljs-string, .hljs-title, .hljs-section, .hljs-attribute, .hljs-literal, .hljs-template-tag, .hljs-template-variable, .hljs-type, .hljs-addition { color: #1a4a7a !important; }
.hljs-comment, .hljs-quote, .hljs-deletion, .hljs-meta { color: var(--g2) !important; font-style: italic; }
.hljs-number, .hljs-symbol, .hljs-bullet, .hljs-link, .hljs-variable, .hljs-regexp { color: #7a4a1a !important; }
.hljs-emphasis { font-style: italic; }
.hljs-strong { font-weight: 700; }

/* 行内格式 */
.mes_text > :is(p, ul, ol, blockquote, h1, h2, h3, h4, h5, h6, table) strong, .mes_text > :is(p, ul, ol, blockquote, h1, h2, h3, h4, h5, h6, table) b { font-family: var(--hei); font-weight: 700; }
.mes_text > :is(p, ul, ol, blockquote, h1, h2, h3, h4, h5, h6, table) del, .mes_text > :is(p, ul, ol, blockquote, h1, h2, h3, h4, h5, h6, table) s { color: var(--g2); }
.mes_text > :is(p, ul, ol, blockquote, h1, h2, h3, h4, h5, h6, table) mark { background: #fbe9e9; color: var(--ink); padding: 0 2px; }
.mes_text > details:not([style]) { border-left: 3px solid var(--ink); padding: 4px 10px; margin: 0.5em 0; background: var(--band); }
.mes_text > details:not([style]) > summary { font-family: var(--hei); cursor: pointer; }

/* =====================================================================
   按钮状态色
   现状：drawers.css:142-159 已经把 .menu_button 基础态改成白底 1px 墨线
   墨字，hover 是 var(--band)（public/style.css:3818 .menu_button、
   :3840-3842 :hover/.active 原来共用同一个 var(--white30a)，本主题在
   drawers.css 里已把 hover 单独拆出来）。这里只补三类还没处理的状态：
   1) 真正的按下/选中/开启态改红底白字；2) 禁用态统一 opacity:.4；
   3) API 连接按钮的默认态目前被 drawers.css:153-159 的
   .menu_button.api_button 规则常态染红，改回默认白底，只在按下时变红。
   查实依据：
   - public/style.css:3088-3093 .menu_button[disabled]/.disabled
     （原为 filter:brightness(75%) grayscale(1); opacity:.5）
   - public/style.css:3096-3122 .menu_button.toggleable(.toggled)
   - public/style.css:3125-3127 .fav_on（原 color:var(--golden)，
     public/script.js:8932 `$('#favorite_button').toggleClass('fav_on', state)`
     确认 #favorite_button 就是 .menu_button，见 index.html:6058）
   - public/style.css:3130-3132 .toggleEnabled（原 color:var(--active)）；
     真实用到 .menu_button.toggleEnabled 组合的地方：
     public/scripts/textgen-settings.js:508
     `$(...).find('.menu_button').toggleClass('toggleEnabled', isEnabled)`
   - public/index.html:2367 #api_button、:2408 #api_button_novel、
     :2888 #api_button_textgenerationwebui、:4056 #api_button_openai，
     均为 .api_button.menu_button；public/script.js:850/855 只在“连接中”
     加/去 .disabled，没有单独的“连接中”视觉类，故这里只处理
     :active 的按下瞬间变红，没有伪造一个不存在的 connecting 类
   - public/index.html:6064 #export_button、:6056 #rm_button_back，
     均为普通 .menu_button，跟随通用规则，未单独覆盖
   - #set_character_world 在当前源码里只作为 <option> 用（index.html:6076，
     6066 处对应的 div 版本被注释掉了），不是按钮，本节不处理
   - public/css/tags.css:189-192 .tag.selected（原 opacity/filter 语义，
     本主题 drawers.css:264 已改成墨黑底白字，这里改成红底白字）；
     :194-199 .tag.excluded 源码语义是“变亮 + 红色描边”，本主题未改动
     其颜色，只是确认没被别处压掉
   - public/style.css:2751-2763 .right_menu_button/.active/:hover
     （原 filter:brightness()）；这类是纯图标无边框按钮，不套白底方框，
     跟 .mes_button（popups.css 五、消息按钮 已处理为 hover 变红）同一种
     处理方式：只变图标颜色
   - .menu_button.selected：当前 ST 1.18 源码里没有任何地方把 .selected
     和 .menu_button 组合使用（scripts/*.js 搜索无命中），这条是防御性
     预留，不代表已查到真实触发点
   - input[type=checkbox] 的勾选颜色已在 drawers.css:179 改红
     （对应 public/style.css:4073 .../::before{box-shadow:inset 1em 1em
     var(--SmartThemeCheckboxTickColor)}），本节不重复
   ===================================================================== */

.menu_button:not(.disabled):not([disabled]):active,
.menu_button.selected,
.menu_button.toggleEnabled,
.menu_button.toggleable.toggled,
#favorite_button.fav_on {
    background: var(--red) !important;
    border-color: var(--red) !important;
    color: #fff !important;
}

.menu_button[disabled],
.menu_button.disabled {
    filter: none !important;
    opacity: .4 !important;
}

/* API 面板「连接」按钮：drawers.css 153-159 把 .api_button 设成常态红底，
   这里覆盖回默认白底墨线墨字，只有真正按下时才变红 */
.menu_button.api_button {
    background: var(--paper) !important;
    border-color: var(--ink) !important;
    color: var(--ink) !important;
}

.menu_button.api_button:hover {
    background: var(--band) !important;
    border-color: var(--ink) !important;
    color: var(--ink) !important;
}

.menu_button.api_button:not(.disabled):not([disabled]):active {
    background: var(--red) !important;
    border-color: var(--red) !important;
    color: #fff !important;
}

/* 标签 chip 选中态：drawers.css:264 原是墨黑底，这里改红底白字 */
.tag.selected {
    background: var(--red) !important;
    border-color: var(--red) !important;
    color: #fff !important;
}

/* 纯图标按钮（无白底方框）：hover / 激活态只变图标颜色，不加背景框 */
.right_menu_button:hover,
.right_menu_button.active {
    filter: none !important;
    color: var(--red) !important;
}

/* =====================================================================
   开关状态适配 —— 用户设置里每个开关打开时本主题都要站得住
   逐条查实 public/scripts/power-user.js 与 public/css/toggle-dependent.css
   （下称 tdc）、public/style.css、public/script.js（v1.18.0）
   ===================================================================== */

/* ---------- 1. 显示头像 hideChatAvatars_enabled + avatar_style ----------
   power-user.js:501 `$('body').toggleClass('hideChatAvatars', ...)`
   （默认 true，见 power-user.js:197）；:1036-1038 avatar_style 0 圆(无
   class)/1 矩形 body.big-avatars/2 方 body.square-avatars/3 圆角
   body.rounded-avatars（power-user.js:95-100 avatar_styles 枚举）。
   tdc:28 `body.hideChatAvatars .mesAvatarWrapper .avatar{display:none}`
   ——只隐藏头像本身，不隐藏 .mesAvatarWrapper 这个容器（见下面第 3 条）。
   现状问题：chat.css:93/104 只在 body:not(.hideChatAvatars) 时把 .mes
   切回 display:flex，但没有约束 .mesAvatarWrapper 的宽度、也没有让
   .mes_block 参与 flex 分配（ST 自己的 .mes_block 只在 style.css:1508
   写死 width:100%，在 flex 容器里当 flex-basis:100% 又没有 min-width:0，
   于是和头像列一起挤爆，文字绕到头像下面；user 消息头像同理挤着名字）。
   头像本身的 1px 边框+box-shadow 来自 style.css:1448-1456 .avatar img。
   头像尺寸变量：style.css:122-126 --avatar-base-width/height:50px，
   toggle-dependent.css:171 大头像(RECTANGULAR) = 50*1.2 宽 × 50*1.8 高
   （--big-avatar-width/height-factor，style.css:1173-1176）。 */
body:not(.hideChatAvatars) .mes {
    display: flex;
    align-items: flex-start;
    gap: 10px;
}

body:not(.hideChatAvatars) .mesAvatarWrapper {
    flex: none;
    width: var(--avatar-base-width);
}

body.big-avatars:not(.hideChatAvatars) .mesAvatarWrapper {
    width: calc(var(--avatar-base-width) * var(--big-avatar-width-factor));
}

body:not(.hideChatAvatars) .mes_block {
    flex: 1;
    min-width: 0;
}

/* 头像本身：墨线代替原阴影，不强改 border-radius——圆形样式(默认，无
   avatar_style class)因此保留圆，矩形/方/圆角三种样式沿用 tdc 里各自
   的 border-radius，只统一边框和去阴影 */
.mesAvatarWrapper .avatar,
.mesAvatarWrapper .avatar img {
    border: 1px solid var(--ink) !important;
    box-shadow: none !important;
}

/* ---------- 2. 聊天时间戳 timestamps_enabled ----------
   body.no-timestamps 时隐藏（tdc:24 `body.no-timestamps .timestamp
   {display:none!important}`，默认 timestamps_enabled:true 所以默认
   不带 no-timestamps，见 power-user.js 里 timestamps_enabled 默认值
   及其对应 `$('body').toggleClass('no-timestamps', !...)` 调用）。
   DOM：index.html:7396 `<small class="timestamp">` 就在 name_text
   之后、mes_buttons 之前，chat.css:114-122 已把 .ch_name 及其内部
   .flex-container 全部 display:inline，所以时间戳天然跟在前缀后面、
   不破坏首段同行；popups.css:551-555 已给 DIN+灰，这里只补字号 */
.timestamp {
    font-size: 0.75em;
}

/* ---------- 3. 楼层号 / Token 数 / 计时器 + 头像隐藏的联动 ----------
   三者 DOM 都在 .mesAvatarWrapper 里（index.html:7381-7387）：
   .mesIDDisplay / .mes_timer / .tokenCounterDisplay，各自独立开关
   （mesIDDisplay_enabled → body.no-mesIDDisplay，
   message_token_count_enabled → body.no-tokenCount，
   timer_enabled → body.no-timer，均见 tdc:24-28）。
   查实结论：tdc:28 只写 `.mesAvatarWrapper .avatar{display:none}`，
   并没有把 .mesAvatarWrapper 本身也一起隐藏——所以头像关闭时这三行
   本该还留在 DOM 里显示。但本主题 chat.css:93 在 hideChatAvatars 下
   把 .mes 改成 display:block（不再是 flex 容器），.mesAvatarWrapper
   作为第一个块级子元素会撑满整行，把这三行小字堆成一条通栏，
   不是"左侧窄列"。这里让它在 hideChatAvatars 下退化成浮动窄列，
   三行竖排；仿照 tdc:42 `body.hideChatAvatars.no-timer.no-tokenCount
   .no-mesIDDisplay .swipe_left{left:0px}` 的写法，三个都关时整块隐藏 */
body.hideChatAvatars .mesAvatarWrapper {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
    float: left;
    width: auto;
    margin: 2px 8px 4px 0;
}

body.hideChatAvatars.no-timer.no-tokenCount.no-mesIDDisplay .mesAvatarWrapper {
    display: none;
}

body.hideChatAvatars .mesAvatarWrapper .mesIDDisplay,
body.hideChatAvatars .mesAvatarWrapper .mes_timer,
body.hideChatAvatars .mesAvatarWrapper .tokenCounterDisplay {
    font-family: var(--din);
    color: var(--g2);
    font-size: 0.75em;
    opacity: 0.8;
}

/* ---------- 4. 模型图标 timestamp_model_icon ----------
   power-user.js:486 `$('body').toggleClass('no-modelIcons', !...)`
   （关闭 tdc:27 `body.no-modelIcons .icon-svg{display:none!important}`）。
   DOM 由 script.js:1925/1963 动态插入：`createModelIcon()` 生成
   `<img class="icon-svg">`，`insertIcon('timestamp-icon', '.timestamp')`
   把它连同 class="timestamp-icon" 一起插到 .timestamp 后面，同一个
   inline 的 flex-container 里，SVGInject 后变成内联 <svg>，用 filter
   转灰度即可，不必再管 display */
.timestamp-icon {
    width: 16px;
    height: 16px;
    filter: grayscale(1);
    opacity: 0.7;
    vertical-align: -3px;
}

/* ---------- 5. 聊天风格 chat_display ----------
   power-user.js chat_styles: DEFAULT:0(无 class，本主题按此设计)/
   BUBBLES:1 body.bubblechat / DOCUMENT:2 body.documentstyle
   （power-user.js:1053-1066 三选一切换 body class）。
   文档模式问题：tdc:354-360
   `body.documentstyle #chat .mes .mesAvatarWrapper,
    body.documentstyle #chat .mes .mes_block .ch_name .name_text,
    body.documentstyle #chat .mes .mes_block .ch_name .timestamp,
    body.documentstyle #chat .mes .mes_block .ch_name .timestamp-icon,
    body.documentstyle .mes:not(.last_mes) .ch_name .mes_buttons
    {display:none!important}`
   —— name_text 被 5 层选择器 + !important 强制隐藏，访谈体前缀会消失。
   这里用完全相同的选择器链把 name_text 拉回来（子选择器完全一致，
   加载顺序 fixes.css 最后合并，等特异性下按后来者覆盖）。
   气泡模式：tdc:306-315 body.bubblechat .mes 有 padding/border-radius/
   背景色/border，这里压平成本主题白纸+细线 */
body.documentstyle #chat .mes .mes_block .ch_name .name_text {
    display: inline !important;
}

body.bubblechat .mes {
    padding: 6px 10px;
    border-radius: 0;
    background-color: var(--paper) !important;
    border: 1px solid var(--rule);
    margin-bottom: 6px;
}

body.bubblechat .mes[is_user="true"] {
    background-color: var(--band) !important;
}

/* ---------- 6. 视觉小说模式 waifuMode ----------
   power-user.js:977 `$('body').toggleClass('waifuMode', ...)`；
   tdc:389-424：#top-bar 加 border-radius:0 0 20px 20px、#chat 加
   border-radius:20px 20px 0 0（本主题都是直角纸面，这里压平回 0）；
   #expression-holder / .zoomed_avatar 只设了 filter drop-shadow，
   style.css 全文没有给 #expression-holder 单独写 background（已查实
   `grep expression-holder style.css` 无背景声明），所以不会自带黑底，
   只要 #chat/#bg1 已经是纸色（chat.css:70-77 已强制 --paper）就不会
   出现黑底；这里只需去掉圆角、确认文字仍读得清（.mes 本身样式不受
   waifuMode 影响，沿用第 1-5 条即可） */
body.waifuMode #top-bar,
body.waifuMode #chat {
    border-radius: 0 !important;
}

/* ---------- 7. 自动展开消息操作菜单 expand_message_actions ----------
   power-user.js:506 `$('body').toggleClass('expandMessageActions', ...)`；
   tdc:472-478：常态显示 .extraMesButtons、隐藏 .extraMesButtonsHint
   （原来悬浮才出现的一排按钮变成常显）。chat.css:166-170 已把
   .mes .ch_name .mes_buttons 定位在段落右上角绝对定位，这里只处理
   按钮排布本身：靠右、灰色、hover 变红，不遮住前缀（前缀是 inline
   文本，按钮绝对定位不占文档流，本来就不会遮挡） */
body.expandMessageActions .mes .ch_name .extraMesButtons {
    display: inline-flex !important;
    gap: 2px;
}

body.expandMessageActions .mes .ch_name .mes_button {
    color: var(--g2);
}

body.expandMessageActions .mes .ch_name .mes_button:hover {
    color: var(--red);
}

/* ---------- 8. 给所有消息分配备选编号 show_swipe_num_all_messages ----------
   power-user.js:536 `$('body').toggleClass('swipeAllMessages', ...)`；
   style.css:1306 `body.swipeAllMessages .mes:not(.last_mes)
   .swipes-counter{opacity:.3;display:flex}`。popups.css:540-543 已把
   .swipes-counter 设成 DIN + var(--g2)，本条打开后沿用同一条规则，
   不需要额外覆盖，这里只是确认查实、不重复写 */

/* ---------- 9. 禅意滑块 enableZenSliders ----------
   power-user.js:201 默认 false，:593-596 `$('body').toggleClass(
   'enableZenSliders', ...)`；实际滑块由 :632 起 CreateZenSliders()
   用 jQuery UI `.slider()` 生成，容器 id 为 `${sliderID}_zenslider`
   （:795），手柄类名固定是 jQuery UI 自带的 `.ui-slider-handle`
   （:805/:904，非 ST 自定义类），原始 <input class="neo-range-slider">
   被 originalSlider.hide() 隐藏（:897）。style.css:4906-4960 已经给
   .ui-slider / .ui-slider-handle 一套 ST 默认样式，这里覆盖成本主题
   墨系配色：轨道细灰、把手红、手柄上的数值文本用 DIN */
body.enableZenSliders .ui-slider {
    background: var(--rule) !important;
    border: 0 !important;
    height: 2px !important;
}

body.enableZenSliders .ui-slider-handle {
    background: var(--red) !important;
    border: 1px solid var(--red) !important;
    color: #fff !important;
    font-family: var(--din) !important;
}

/* ---------- 10. 角色卡热切换 hotswap_enabled ----------
   power-user.js:192 默认 true，:471 `$('body').toggleClass(
   'no-hotswap', !hotswap_enabled)`；DOM 容器 index.html:6007
   `<div id="HotSwapWrapper">`，内部 .hotswap .avatar 由 script.js
   动态填充角色头像；style.css:1420-1423 .hotswap 只给了 margin，
   没有单独给 .avatar 加边框，跟随全局 .avatar img 的
   1px solid var(--SmartThemeBorderColor) + box-shadow。这里改成
   细墨线方形小头像，去阴影 */
#HotSwapWrapper .hotswap .avatar,
#HotSwapWrapper .hotswap .avatar img {
    border: 1px solid var(--ink) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}

/* ---------- 11. 标签作为文件夹 bogus_folders ----------
   style.css:3276 起 .bogus_folder_select 与 .character_select 共用
   目录页规则，drawers.css:224-244 已经把 #rm_print_characters_block
   里的 .bogus_folder_select 改成黑体名（.ch_name）+ 无圆角头像 +
   悬停灰底；.bogus_folder_counter 的计数字体目前跟随 .ch_name 的
   黑体，这里单独把计数改成 DIN 灰，呼应目录页里"篇数"的排版感 */
#rm_print_characters_block .bogus_folder_select .bogus_folder_counter {
    font-family: var(--din);
    color: var(--g2);
}

/* ---------- 12. 可移动 UI 面板 movingUI ----------
   power-user.js:1007 `$('body').toggleClass('movingUI', ...)`；
   tdc:445-455：body.movingUI .drag-grabber 从 display:none 变
   display:inline（抓手图标本来就隐藏，movingUI 打开才露出来），
   同时给 #sheld/.drawer-content/#expression-holder/.zoomed_avatar/
   .draggable/#floatingPrompt 加 resize:both。抓手本身没有专门的
   颜色规则（跟随图标默认色），这里改成墨色；面板背景/边框沿用
   drawers.css 里已经给的白纸+细线，不需要重复声明 */
body.movingUI .drag-grabber {
    color: var(--ink) !important;
}

/* ---------- 13. 其余开关：确认无视觉冲突 ----------
   减少动态效果 reduced_motion（power-user.js:526 body.reduced-motion，
   本主题没有自定义 transition/animation，只依赖 ST 自带的，不冲突）；
   疯狂实验室模式 enableLabMode（只解锁数值范围，无独立 CSS class，
   不影响视觉）；单击编辑消息 click_to_edit（power-user.js:340，纯
   交互行为，改的是点击进入编辑态而非样式，不冲突）；头像悬停放大
   zoomed_avatar_magnification（power-user.js:305，触发 .zoomed_avatar
   浮层，样式来自 style.css:4104 附近，本主题未覆盖 .zoomed_avatar，
   不冲突）。以上四项逐一查过 power-user.js 对应行号，确认没有与
   本主题选择器交叉，不需要额外规则。 */

/* 头像隐藏时的楼层/Token/计时器窄列：与段前小标题留出间距 */
body.hideChatAvatars .mes .mesAvatarWrapper {
    margin-right: 14px !important;
}

/* =====================================================================
   预设 / 提示词管理器（css/promptmanager.css）
   问题：禁用条目名字用 --white30a，白纸上看不见；长名字压到右侧图标
   ===================================================================== */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--g2) !important;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    text-decoration: line-through;
    text-decoration-color: var(--rule);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt > span:first-child,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name {
    min-width: 0 !important;
    overflow: hidden !important;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name {
    display: flex !important;
    align-items: center;
    gap: 4px;
    white-space: nowrap;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    align-items: center !important;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .prompt_manager_prompt_controls {
    background: var(--paper);
    position: relative;
    z-index: 1;
}

#completion_prompt_manager .completion_prompt_manager_header,
#completion_prompt_manager .completion_prompt_manager_header div,
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    color: var(--g1) !important;
    text-shadow: none !important;
    filter: none !important;
}

/* 启用 / 禁用开关：启用墨色，禁用灰 */
#completion_prompt_manager .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    color: var(--ink) !important;
    opacity: 1 !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt_disabled .prompt-manager-toggle-action {
    color: var(--g2) !important;
}

/* =====================================================================
   滑动切换箭头：原样式绝对定位在左下，会压住正文首字 → 并到右下与计数器一起
   ===================================================================== */
#chat .mes .swipe_left {
    left: auto !important;
    right: 46px !important;
    bottom: calc(var(--swipeCounterHeight, 12px) + var(--swipeCounterMargin, 4px)) !important;
}

/* =====================================================================
   Toast：紧凑版（MVU 等脚本一次会弹很多条）
   ===================================================================== */
#toast-container > div {
    width: 300px !important;
    padding: 6px 12px 6px 14px !important;
    font-size: 13px !important;
    line-height: 1.45 !important;
    margin-bottom: 6px !important;
}

#toast-container > div::before {
    display: inline !important;
    font-size: 11px !important;
    margin-right: 6px;
}

#toast-container .toast-title {
    display: inline;
    font-size: 13px !important;
}

#toast-container .toast-message {
    font-size: 12.5px !important;
    color: var(--g1) !important;
}

/* =====================================================================
   状态语义色（research/state-colors.md 扫描结果）
   原先所有状态都挤在三联红里，且有 3 处被主题通用规则压掉：
   .world_set 绿、收藏角色金色名字、.tag.excluded 红框。
   映射：链接/启用/已连接 = --ok 苔绿；收藏 = --fav 赭金；
         关闭/错误/已排除 = --err 暗砖红；选中/按下 = --red 三联红。
   ===================================================================== */

/* 世界书已链接（角色卡 #world_button、聊天 .chat_lorebook_button、人设 #persona_lore_button）
   world-info.js:5559/5569/1015/1180/5859/5862，personas.js:641/1305 */
.menu_button.world_set,
#world_button.world_set,
#set_character_world.world_set,
.chat_lorebook_button.world_set,
#persona_lore_button.world_set {
    color: var(--ok) !important;
    border-color: var(--ok) !important;
    background: var(--ok-bg) !important;
}

/* 收藏：按钮 script.js:8932、group-chats.js:2008；角色列表 is_fav script.js:952/7514 */
#favorite_button.fav_on,
#group_favorite_button.fav_on,
.menu_button.fav_on,
.fav_on {
    color: var(--fav) !important;
    border-color: var(--fav) !important;
    background: var(--fav-bg) !important;
}

#rm_print_characters_block .character_select.is_fav .ch_name,
#rm_print_characters_block .group_select.is_fav .ch_name,
.character_select.is_fav .ch_name,
.group_select.is_fav .ch_name {
    color: var(--fav) !important;
}

.character_select.is_fav .avatar,
.group_select.is_fav .avatar,
.avatar.is_fav,
.group_member.is_queued {
    outline: 2px solid var(--fav) !important;
}

.group_member.is_active,
.avatar.is_active {
    outline: 2px solid var(--ok) !important;
}

/* 开关开启：instruct-mode.js / sysprompt.js / power-user.js / samplerSelect.js 的 .toggleEnabled，通用 .toggleable.toggled */
.menu_button.toggleEnabled,
.menu_button.toggleable.toggled {
    color: #ffffff !important;
    background: var(--ok) !important;
    border-color: var(--ok) !important;
}

/* 开关关闭：原版红字 / 红叉 */
.menu_button.togglable:not(.toggleEnabled),
.menu_button.toggleable:not(.toggled)::before {
    color: var(--err) !important;
}

/* 标签：选中三联红（保留），已排除 = 暗砖红框 + 删除线（tags.css:194-210） */
.tag.excluded,
.tags .tag.excluded {
    border-color: var(--err) !important;
    color: var(--err) !important;
    text-decoration: line-through;
}

/* API 已连接绿点 script.js:812；断线图标 RossAscends-mods.js:333 */
.online_status_indicator.success {
    background: var(--ok) !important;
}

#API-status-top.redOverlayGlow {
    color: var(--err) !important;
}

/* 世界书条目开关（world-info.js:3253-3262）、提示词启用开关 */
.world_entry .killSwitch.fa-toggle-on,
#completion_prompt_manager .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    color: var(--ok) !important;
}

.world_entry .killSwitch.fa-toggle-off,
#completion_prompt_manager .completion_prompt_manager_prompt_disabled .prompt-manager-toggle-action {
    color: var(--g2) !important;
}

/* 消息多选：原版 rgb(102,0,0) 深红底在白纸上看不清字（style.css:1192） */
#chat .mes.selected {
    background: var(--err-bg) !important;
    box-shadow: inset 3px 0 0 var(--red);
}

/* 提示词管理器出错框 promptmanager.css:215 */
.completion_prompt_manager_error {
    border-color: var(--err) !important;
}

/* =====================================================================
   酒馆助手前端卡（research/jshelper.md）：.TH-render > iframe
   iframe 高度由它的 ResizeObserver 写内联 style.height，主题不得改 height/overflow
   ===================================================================== */
.mes_text .TH-render {
    display: block;
    clear: both;
    margin: 0.4em 0;
}

.mes_text .TH-render iframe {
    display: block;
    max-width: 100%;
    border: 0;
    background: transparent;
}

/* =====================================================================
   卡片 / 预设正则插入的 HTML：不继承正文的两端对齐和首行缩进
   （排版规则已收窄到 .mes_text 的直接子元素，research/mvu.md 清单 B-1）
   ===================================================================== */
.mes_text > :is(div, section, article, center, details[style]) {
    text-align: start;
    text-indent: 0;
}

/* =====================================================================
   加载页（css/loader.css:58-90 #loader.splash-screen / .splash-logo / #load-spinner / .splash-message）
   杂志风：白纸、三联刊标、细红线进度条、黑体小字
   ===================================================================== */
#loader.splash-screen {
    background: var(--paper) !important;
    backdrop-filter: none !important;
}

#loader.splash-screen .splash-logo {
    width: min(300px, 70vw) !important;
    height: 92px !important;
    object-position: -9999px 0;
    background: var(--sanlian-logo) center / contain no-repeat;
    filter: none !important;
    box-shadow: none !important;
}

#loader.splash-screen #load-spinner {
    display: block !important;
    width: 160px;
    height: 2px;
    margin: 26px auto 0;
    font-size: 0 !important;
    color: transparent !important;
    background: linear-gradient(90deg, var(--red) 0 35%, var(--rule) 35% 100%);
    background-size: 200% 100%;
    animation: sanlian-press 1.2s linear infinite !important;
}

@keyframes sanlian-press {
    from { background-position: 100% 0; }
    to { background-position: -100% 0; }
}

#loader.splash-screen .splash-message {
    font-family: var(--hei) !important;
    font-size: 13px !important;
    letter-spacing: 0.3em;
    color: var(--g1) !important;
    border: 0 !important;
    text-shadow: none !important;
}

#loader.splash-screen .splash-message::before {
    content: "本期付印中 · ";
    color: var(--red);
}
